import { Group, Mesh, PlaneGeometry, Vector3, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  const root = new Group();
  const disposables = [];

  // Apply cinematic primitives if any
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((p) => {
      const prim = ctx.primitives[p.name];
      if (prim) {
        const result = prim(root, p.params);
        if (result?.cleanup) {
          disposables.push(() => result.cleanup());
        }
        if (result?.timeline) {
          disposables.push(() => result.timeline.kill());
        }
      }
    });
  }

  // Texted plane based on atlas region (default 512x320)
  const atlas = config.atlasRegion || { width: 512, height: 320 };
  const aspect = atlas.width / atlas.height;
  const planeWidth = aspect; // height = 1 unit
  const planeHeight = 1;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Cleanup geometry & material
  disposables.push(() => {
    geometry.dispose();
    material.dispose();
  });

  // Create text objects
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  items.forEach((item) => {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'left',
    });
    // Position text slightly above the plane
    txt.position.set(0, planeHeight / 2 + 0.1, 0.01);
    root.add(txt);
    // Dispose text resources
    disposables.push(() => {
      if (txt.geometry) txt.geometry.dispose?.();
      if (txt.material) txt.material.dispose?.();
    });
  });

  // Billboard update handler (rotate around Y to face camera)
  root.userData.handlers = {
    update: (renderer, scene, camera) => {
      const worldPos = new Vector3();
      root.getWorldPosition(worldPos);
      const camPos = camera.position.clone();
      const dir = camPos.sub(worldPos).normalize();
      const angle = Math.atan2(dir.x, dir.z);
      root.rotation.set(0, angle, 0);
    },
  };

  // Cleanup function
  root.userData.cleanup = () => {
    disposables.forEach((fn) => fn());
    // Kill any GSAP timelines that might have been created elsewhere
    gsap.globalTimeline.clear();
  };

  return root;
}
